{
  "name": "opencode-moshi-live",
  "version": "0.1.1",
  "description": "OpenCode plugin for Moshi Live Activity and notifications",
  "type": "module",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/young5lee/opencode-moshi-live.git"
  },
  "homepage": "https://github.com/young5lee/opencode-moshi-live#readme",
  "bugs": {
    "url": "https://github.com/young5lee/opencode-moshi-live/issues"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "moshi",
    "notifications",
    "live-activity"
  ],
  "main": "index.ts",
  "module": "index.ts",
  "files": [
    "index.ts",
    "src/cli.ts",
    "README.md",
    "LICENSE"
  ],
  "exports": {
    ".": "./index.ts"
  },
  "bin": {
    "opencode-moshi-live": "src/cli.ts"
  },
  "scripts": {
    "typecheck": "bunx tsc --noEmit"
  },
  "engines": {
    "bun": ">=1.3.0"
  },
  "dependencies": {
    "@opencode-ai/plugin": "^1.4.7"
  },
  "devDependencies": {
    "@types/bun": "latest",
    "typescript": "^5.8.2"
  },
  "peerDependencies": {
    "typescript": "^5"
  }
}
